let data;try{data=JSON.parse(localStorage.getItem('kubra-ops-v1'))||initialData()}catch{data=initialData()}
let role='manager',view='dashboard',period='2026-09',filter='',region='all';
const save=()=>localStorage.setItem('kubra-ops-v1',JSON.stringify(data));
function notify(t){const e=$('#toast');e.textContent=t;e.style.display='block';clearTimeout(window.__toast);window.__toast=setTimeout(()=>e.style.display='none',3600)}
function badge(s){let c=/geç|Sorun|fark|bulunamadı|Süresi/.test(s)?'red':/bekliyor|Taslak|Hazırlanıyor|Bugün/.test(s)?'amber':/eşleşti|Onaylandı|Yayında|Kabul|Güncel|Teslim alındı/.test(s)?'green':'blue';return `<span class="badge ${c}">${esc(s)}</span>`}
function card(title,body,action=''){return `<section class="card"><div class="cardhead"><h2>${title}</h2>${action}</div>${body}</section>`}
function kpi(label,value,note,go='',cls=''){return `<button class="kpi ${cls}" ${go?`onclick="navigate('${go}')"`:''}><span class="label">${label}<span>↗</span></span><strong>${value}</strong><small>${note}</small></button>`}
function rows(items,render,cols){return items.length?items.map(render).join(''):`<tr><td class="empty" colspan="${cols}">Bu görünümde kayıt bulunmuyor.</td></tr>`}
function scoped(a){if(role==='branch')return a.filter(x=>!x.region||x.region.includes('Mandarin Etiler')||x.person==='Öykü Demir');if(role==='engineer')return a.filter(x=>!x.region||x.region.includes('Haseki ATR')||x.person==='Emre Aydın');if(role==='driver')return a.filter(x=>x.person==='Murat Çelik'||x.from==='Murat Çelik'||x.to==='Murat Çelik');return a}
function setRole(r){role=r;view=['engineer','driver'].includes(r)?'mobile':'dashboard';filter='';render()}
function navigate(v){view=v;filter='';closeModal();render();scrollTo(0,0)}
function resetDemo(){if(confirm('Bu tarayıcıdaki tüm demo işlemleri sıfırlansın mı?')){data=initialData();save();render();notify('Demo başlangıç verilerine döndü.')}}
function render(){const r=ROLES[role],nav=NAV[role];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="logo"><i>✣</i> connect master</div><div class="company"><strong>Kübra Catering</strong><small>Operasyon, finans ve satış merkezi<br>Canlı sistem prototipi</small></div><nav>${nav.map(([id,ic,l])=>`<button class="${view===id?'active':''}" onclick="navigate('${id}')"><span class="nav-icon">${ic}</span>${l}${navAlert(id)}</button>`).join('')}</nav><div class="sidebar-foot">Demo verileri bu tarayıcıda saklanır.<br><button onclick="resetDemo()">Demoyu sıfırla</button></div></aside><main class="main"><header class="header"><div class="header-title">Kübra Catering <small>Connect Master</small></div><div class="header-right"><div class="rolebox" aria-label="Rol görünümü">${Object.entries(ROLES).map(([id,x])=>`<button class="${role===id?'active':''}" onclick="setRole('${id}')" title="${x.label}">${x.label.replace('Bölge ','').replace(' Sorumlusu','')}</button>`).join('')}</div><div class="user"><span class="avatar">${r.initial}</span><span class="identity"><b>${r.person}</b><small>${r.label} · ${r.scope}</small></span></div></div></header><div class="content">${page()}<p class="footnote">Gerçekçi temsili kayıtlar · Veritabanı ve canlı banka/Mikro bağlantısı yoktur · İşlemler yalnız bu tarayıcıdaki demoyu günceller.</p></div></main></div>`}
function navAlert(id){const n=id==='purchases'?data.purchases.filter(x=>x.status!=='Tam eşleşti').length:id==='documents'?data.documents.filter(x=>/bekliyor|Gecikmiş/.test(x.status)).length:id==='bank'?data.bank.filter(x=>x.status!=='Otomatik eşleşti').length:0;return n?`<span class="nav-count">${n}</span>`:''}
function head(title,desc,actions=''){return `<div class="pagehead"><div><div class="eyebrow">KÜBRA CATERING / ${ROLES[role].label}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function page(){return view==='dashboard'?dashboard():view==='mobile'?mobile():view==='materials'?materials():view==='expenses'?expenses():view==='purchases'?purchases():view==='costs'?costs():view==='documents'?documents():view==='accounts'?accounts():view==='bank'?bank():view==='offers'?offers():view==='catalog'?catalog():webai()}

function dashboard(){const diffs=data.expenses.filter(x=>x.status==='Tutar farkı').length,pdiff=data.purchases.filter(x=>x.status!=='Tam eşleşti').length,overdue=data.accounts.filter(x=>x.days>0).reduce((s,x)=>s+x.due,0),unmatched=data.bank.filter(x=>x.status!=='Otomatik eşleşti').length;if(role==='branch')return branchDashboard();if(role==='documents')return documentsDashboard();if(role==='finance')return financeDashboard();if(role==='procurement')return procurementDashboard();return head('Yönetim Merkezi','Şirket genelindeki kritik hareketleri ve yalnız müdahale gerektiren işleri tek ekrandan yönetin.',`<select class="input" onchange="period=this.value;render()"><option>Eylül 2026</option><option>Ağustos 2026</option></select>`)+`<div class="kpis">${kpi('Bugün malzeme hareketi',data.materials.filter(x=>x.date==='2026-09-27').length,'2 giriş · 1 transfer','materials')}${kpi('Fatura / kayıt farkı',diffs+pdiff,'Tutar, fiyat veya miktar farkı','purchases','critical')}${kpi('Vadesi geçen',money(overdue),'2 cari takip bekliyor','accounts','urgent')}${kpi('Banka eşleştirme',unmatched,'Finans kararı gerekli','bank')}</div><div class="grid"><div class="stack">${card('Öncelikli işler',`<div class="alert-list">${alertRow(data.purchases.filter(x=>x.region==='Belirsiz').length,'Şubeye yönlendirilemeyen fatura','Proje, cari veya tedarikçi eşleşmesi seçilmeli','purchases')}${alertRow(diffs,'Harcama–fatura tutarı farklı','Beyan edilen tutarla gelen belge uyuşmuyor','expenses')}${alertRow(data.materials.filter(x=>x.status==='Sorunlu').length,'Eksik / sorunlu teslimat','Mal kabul miktarı satın almayla uyuşmuyor','materials')}${alertRow(data.documents.filter(x=>x.status==='Gecikmiş').length,'Geciken evrak','Evrak teslim zinciri tamamlanmadı','documents')}${alertRow(unmatched,'Eşleşmeyen banka hareketi','Cari veya açık fatura kararı bekleniyor','bank')}</div>`)}${card('Bölge operasyon durumu',regionCards())}</div><div class="stack">${card('Bugünkü akış',timeline())}${card('Haftalık kapanış',`<div class="cardbody"><div class="between"><span>Toplanan kayıt</span><b>42 / 47</b></div><div class="progress" style="margin:12px 0"><span style="width:89%"></span></div><p class="muted">5 kayıtta belge veya kontrol eksik. Cuma 17.00 kapanışından önce tamamlanmalı.</p><button class="btn small" onclick="navigate('expenses')">Eksikleri incele</button></div>`)}</div></div>`}
function branchDashboard(){const p=scoped(data.purchases),pending=p.filter(x=>x.status!=='Tam eşleşti');return head('Mandarin Etiler Şube Özeti','Yalnız bu şubeye yönlendirilen faturaları, mal kabulleri ve maliyet durumunu yönetin.')+`<div class="kpis">${kpi('Yeni / yanıtsız fatura',pending.length,'Şube kontrolü bekliyor','purchases','critical')}${kpi('Bugün mal kabul',scoped(data.materials).filter(x=>x.date==='2026-09-27').length,'Teslimatlar','materials')}${kpi('Sorunlu teslimat',scoped(data.materials).filter(x=>x.status==='Sorunlu').length,'Eksik / fazla / hatalı','materials','urgent')}${kpi('Eylül maliyeti',money(p.filter(x=>x.status==='Tam eşleşti').reduce((s,x)=>s+x.invoice,0)),'Onaylı faturalar','costs')}</div><div class="grid"><div class="stack">${card('Kontrol bekleyen faturalar',purchaseTable(pending))}</div><div class="stack">${card('Şube işleyişi',`<div class="cardbody timeline"><div class="timeline-item"><strong>Fatura otomatik eşleşir ve şubeye gelir</strong><small>Proje, cari ve tedarikçi sinyalleri kullanılır.</small></div><div class="timeline-item"><strong>Şube sorumlusu teslimat ve evrakı kontrol eder</strong><small>Eksik, fazla veya hatalı teslimat kaydedilir.</small></div><div class="timeline-item"><strong>Onaylanan tutar aylık maliyete alınır</strong><small>Tekrar yönetici onayı oluşmaz; yönetici süreci izler.</small></div></div>`)}</div></div>`}
function alertRow(n,t,d,v){return `<button class="alert" onclick="navigate('${v}')"><span class="alert-number">${n}</span><span><strong>${t}</strong><small>${d}</small></span><span class="arrow">›</span></button>`}
function regionCards(){return `<div class="cardbody region-grid">${REGIONS.slice(0,6).map((r,i)=>{const m=data.materials.filter(x=>x.region.includes(r)),issues=m.filter(x=>/Sorun|bekliyor/.test(x.status)).length;return `<div class="region"><div class="between"><b>${r}</b>${issues?badge(issues+' açık işlem'):badge('Güncel')}</div><div class="statline"><span>Haftalık hareket</span><b>${m.length+6+i}</b></div><div class="statline"><span>Haftalık harcama</span><b>${money(18200+i*4350)}</b></div></div>`}).join('')}</div>`}
function timeline(){return `<div class="cardbody timeline"><div class="timeline-item"><strong>Mandarin Etiler mal kabulü açıldı</strong><small>Öykü Demir · 10:42</small></div><div class="timeline-item"><strong>150.000 TL banka hareketi otomatik eşleşti</strong><small>Sistem · 10:18</small></div><div class="timeline-item"><strong>Akaryakıt harcamasında 225 TL fark bulundu</strong><small>Sistem · 09:56</small></div><div class="timeline-item"><strong>IRS-44221 evrakı teslim alındı</strong><small>Emre Aydın · 09:31</small></div></div>`}
function procurementDashboard(){return head('Satın Alma Merkezi','Sipariş, mal kabul ve gelen faturayı üçlü kontrol ederek yalnız istisnalara müdahale edin.')+`<div class="kpis">${kpi('Açık sipariş','12','4 bölge','purchases')}${kpi('Mal kabul bekleyen','4','Teslimat kontrolü gerekli','materials','urgent')}${kpi('Fiyat / miktar farkı','2','İnceleme gerekli','purchases','critical')}${kpi('Bu ay satın alma',money(1842650),'186 kalem','purchases')}</div>${card('Karşılaştırma kuyruğu',purchaseTable(data.purchases.filter(x=>x.status!=='Tam eşleşti')))}`}
function financeDashboard(){return head('Finans Merkezi','Cari vadelerini, gelen faturaları ve banka eşleştirmelerini yönetin.')+`<div class="kpis">${kpi('Toplam alacak',money(1029250),'Müşteri carileri','accounts')}${kpi('Vadesi geçen',money(287810),'3 açık takip','accounts','critical')}${kpi('Eşleşmeyen hareket','3','Banka kararı gerekli','bank','urgent')}${kpi('Bugün tahsilat',money(230500),'4 banka hareketi','bank')}</div><div class="grid equal">${card('Vadesi geçenler',accountTable(data.accounts.filter(x=>x.days>0)))}${card('Banka eşleştirme kuyruğu',bankTable(data.bank.filter(x=>x.status!=='Otomatik eşleşti')))}</div>`}
function documentsDashboard(){return head('Evrak Merkezi','Fiziksel ve dijital evrakların kimden kime geçtiğini, şu anda kimde olduğunu takip edin.')+`<div class="kpis">${kpi('Bugün teslim alınan','7','Tüm evrak türleri','documents')}${kpi('Teslim onayı bekleyen','3','Alıcı onayı gerekli','documents','urgent')}${kpi('Geciken','1','Arşiv teslimi gecikti','documents','critical')}${kpi('Zimmetli','14','Personel üzerindeki evrak','documents')}</div>${card('Evrak hareketleri',documentTable(data.documents))}`}

function mobile(){const isDriver=role==='driver';return head('Mobil Operasyon',`${ROLES[role].person} için yetkili kayıtlar ve son yedi günlük hareketler.`)+`<div class="mobile-shell"><div class="mobile-top"><small>${isDriver?'ARAÇ · 34 KBR 246':'BÖLGE · HASEKİ ATR'}</small><h2>Merhaba, ${ROLES[role].person.split(' ')[0]}</h2><p>${isDriver?'Bugünkü rotanız: Merkez → Sakarya → Haseki':'Bugün tamamlamanız gereken 3 işlem var.'}</p></div><div class="mobile-body"><div class="quick"><button onclick="openForm('${isDriver?'expense':'material'}')"><span>${isDriver?'₺':'⇩'}</span><b>${isDriver?'Harcama gir':'Malzeme girişi'}</b></button><button onclick="openForm('${isDriver?'delivery':'expense'}')"><span>${isDriver?'▤':'₺'}</span><b>${isDriver?'Teslimat kaydet':'Harcama gir'}</b></button></div><div class="notice ${isDriver?'':'warn'}">${isDriver?'ATR Sakarya’dan alınan 48 koli yağ için Haseki teslim onayı bekleniyor.':'SAV20260010007 teslimatında 35 kg domates farkı açık.'}</div>${card('Son 7 günlük hareketler',`<div class="cardbody">${(isDriver?scoped(data.expenses):scoped(data.materials)).slice(0,4).map(x=>`<div class="statline"><span><b>${esc(x.item||x.category)}</b><small>${fmt(x.date)} · ${esc(x.region)}</small></span>${badge(x.status)}</div>`).join('')}</div>`)}</div><div class="mobile-nav"><button class="active">⌂<br>Ana Sayfa</button><button onclick="navigate('materials')">⇄<br>Hareketler</button><button onclick="navigate('expenses')">₺<br>Harcamalar</button><button onclick="navigate('documents')">▤<br>Evraklar</button></div></div>`}

function commonToolbar(placeholder){return `<div class="toolbar"><input class="input search" placeholder="${placeholder}" value="${esc(filter)}" oninput="filter=this.value;render()"><select class="input" onchange="region=this.value;render()"><option value="all">Tüm bölgeler</option>${REGIONS.map(r=>`<option ${region===r?'selected':''}>${r}</option>`).join('')}</select><button class="btn small" onclick="filter='';region='all';render()">Temizle</button></div>`}
function match(x){const q=filter.toLocaleLowerCase('tr');return (!q||JSON.stringify(x).toLocaleLowerCase('tr').includes(q))&&(region==='all'||String(x.region||'').includes(region))}
function materials(){const list=scoped(data.materials).filter(match);return head('Malzeme Hareketleri','Bölgelere giren, çıkan ve transfer edilen malzemeleri belge ve teslim onayıyla takip edin.',`<button class="btn primary" onclick="openForm('material')">+ Malzeme hareketi</button>`)+`<div class="kpis">${kpi('Bu hafta giriş','28','12 farklı tedarikçi')}${kpi('Bölgeler arası transfer','6','1 teslim onayı bekliyor')}${kpi('Sorunlu teslimat',data.materials.filter(x=>x.status==='Sorunlu').length,'Eksik / fazla / hasarlı','','critical')}${kpi('Belgesiz hareket','2','İrsaliye eklenmeli','','urgent')}</div>${commonToolbar('Ürün, tedarikçi veya evrak ara…')}${card('Hareket listesi',materialTable(list))}`}
function materialTable(a){return `<div class="table-wrap"><table><thead><tr><th>TARİH / TÜR</th><th>BÖLGE</th><th>MALZEME</th><th>CARİ / TEDARİKÇİ</th><th>MİKTAR</th><th>EVRAK</th><th>DURUM</th><th></th></tr></thead><tbody>${rows(a,x=>`<tr><td>${fmt(x.date)}<small>${x.type}</small></td><td>${esc(x.region)}</td><td><b>${esc(x.item)}</b><small>${esc(x.person)}</small></td><td>${esc(x.supplier)}</td><td>${x.qty} ${x.unit}</td><td>${esc(x.document||'—')}</td><td>${badge(x.status)}${x.issue?`<small class="amount-diff">${esc(x.issue)}</small>`:''}</td><td><button class="link" onclick="openDetail('material',${x.id})">İncele ›</button></td></tr>`,8)}</tbody></table></div>`}

function expenses(){const list=scoped(data.expenses).filter(match);return head(role==='driver'?'Harcamalarım':'Personel Harcamaları','Mobil girilen harcamaları belge ve gelen faturayla karşılaştırın.',`<button class="btn primary" onclick="openForm('expense')">+ Harcama gir</button>`)+`<div class="kpis">${kpi('Bu hafta beyan',money(data.expenses.reduce((s,x)=>s+x.declared,0)),'5 personel kaydı')}${kpi('Faturayla eşleşen',data.expenses.filter(x=>x.status==='Eşleşti').length,'Tutar ve cari doğrulandı')}${kpi('Tutar farkı',data.expenses.filter(x=>x.status==='Tutar farkı').length,'Toplam 285 TL fark','','critical')}${kpi('Belge bekleyen',data.expenses.filter(x=>x.status==='Belge bekliyor').length,'Fiş veya fatura eksik','','urgent')}</div>${commonToolbar('Personel, cari veya harcama türü ara…')}${card('Harcama kayıtları',expenseTable(list))}`}
function expenseTable(a){return `<div class="table-wrap"><table><thead><tr><th>TARİH / PERSONEL</th><th>BÖLGE</th><th>HARCAMA / CARİ</th><th>BEYAN</th><th>FATURA</th><th>FARK</th><th>BELGE</th><th>DURUM</th></tr></thead><tbody>${rows(a,x=>{const diff=x.invoice==null?null:x.invoice-x.declared;return `<tr><td>${fmt(x.date)}<small>${esc(x.person)} · ${x.role}</small></td><td>${x.region}</td><td><b>${x.category}</b><small>${x.vendor}</small></td><td>${money(x.declared)}</td><td>${x.invoice==null?'—':money(x.invoice)}</td><td class="${diff?'amount-diff':''}">${diff==null?'—':money(diff)}</td><td>${x.doc||'<span class="amount-diff">Eksik</span>'}</td><td>${badge(x.status)}</td></tr>`},8)}</tbody></table></div>`}

function purchases(){const list=scoped(data.purchases).filter(match);return head(role==='finance'?'Gelen Faturalar':'Satın Alma & Fatura Kontrolü','Satın alma, mal kabul ve faturayı aynı kayıt üzerinde karşılaştırın.',`<button class="btn primary" onclick="openForm('purchase')">+ Satın alma kaydı</button>`)+`<div class="notice" style="margin-bottom:16px"><b>Üçlü kontrol:</b> Satın alma kaydı ↔ Mal kabul / irsaliye ↔ Gelen fatura. Uyuşmayan alanlar otomatik olarak alarm oluşturur.</div><div class="kpis">${kpi('Tam eşleşen',data.purchases.filter(x=>x.status==='Tam eşleşti').length,'Otomatik tamamlandı')}${kpi('Fiyat farkı',data.purchases.filter(x=>x.status==='Fiyat farkı').length,'270 TL fark','','critical')}${kpi('Miktar farkı',data.purchases.filter(x=>x.status==='Miktar farkı').length,'35 kg eksik','','critical')}${kpi('Kayıtsız fatura',data.purchases.filter(x=>x.status==='Satın alma kaydı yok').length,'Satın alma kaydı bulunamadı','','urgent')}</div>${commonToolbar('Sipariş, fatura veya tedarikçi ara…')}${card('Satın alma–mal kabul–fatura karşılaştırması',purchaseTable(list))}`}
function purchaseTable(a){return `<div class="table-wrap"><table><thead><tr><th>SATIN ALMA</th><th>BÖLGE / TEDARİKÇİ</th><th>ÜRÜN</th><th>SİPARİŞ / KABUL</th><th>BEKLENEN</th><th>FATURA</th><th>DURUM</th><th></th></tr></thead><tbody>${rows(a,x=>`<tr><td>${x.no}<small>${fmt(x.date)} · ${x.invoiceNo}</small></td><td>${x.region}<small>${x.supplier}</small></td><td>${x.item}</td><td>${x.qty??'—'} / ${x.received??'—'}</td><td>${x.expected==null?'—':money(x.expected)}</td><td>${money(x.invoice)}</td><td>${badge(x.status)}</td><td><button class="link" onclick="openDetail('purchase',${x.id})">Karşılaştır ›</button></td></tr>`,8)}</tbody></table></div>`}

function costs(){const all=role==='branch'?scoped(data.purchases):data.purchases,approved=all.filter(x=>x.status==='Tam eşleşti'),total=approved.reduce((s,x)=>s+x.invoice,0);const byRegion=REGIONS.map(r=>({region:r,total:approved.filter(x=>x.region===r).reduce((s,x)=>s+x.invoice,0),count:approved.filter(x=>x.region===r).length})).filter(x=>role!=='branch'||x.region==='Mandarin Etiler');return head('Aylık Maliyetler','Şube tarafından kontrol edilen faturalar otomatik olarak ayın maliyet tablosuna alınır.',`<select class="input"><option>Eylül 2026</option><option>Ağustos 2026</option></select>`)+`<div class="kpis">${kpi('Onaylı fatura',approved.length,'Maliyete alınan kayıt')}${kpi('Toplam maliyet',money(total),'Eylül 2026')}${kpi('Kontrol bekleyen',all.filter(x=>x.status!=='Tam eşleşti').length,'Henüz maliyete dahil değil','','urgent')}${kpi('Kapsanan şube',byRegion.filter(x=>x.count).length,'Aktif maliyet')}</div>${card('Şube bazlı aylık maliyet',`<div class="table-wrap"><table><thead><tr><th>ŞUBE / PROJE</th><th>ONAYLI FATURA</th><th>MALZEME</th><th>PERSONEL HARC.</th><th>AYLIK TOPLAM</th><th>DURUM</th></tr></thead><tbody>${rows(byRegion,x=>{const ex=data.expenses.filter(e=>e.region===x.region&&e.status==='Eşleşti').reduce((s,e)=>s+e.declared,0);return `<tr><td><b>${x.region}</b><small>Eylül 2026</small></td><td>${x.count}</td><td>${money(x.total)}</td><td>${money(ex)}</td><td><b>${money(x.total+ex)}</b></td><td>${badge(x.count?'Güncel':'Fatura bekliyor')}</td></tr>`},6)}</tbody></table></div>`)}`}

function documents(){const list=scoped(data.documents).filter(x=>!filter||JSON.stringify(x).toLocaleLowerCase('tr').includes(filter.toLocaleLowerCase('tr')));return head('Evrak Alıp Verme','Evrakın kimden alındığını, kime verildiğini ve şu anda kimde olduğunu hareket geçmişiyle izleyin.',`<button class="btn primary" onclick="openForm('document')">+ Evrak kaydı</button>`)+`<div class="kpis">${kpi('Aktif evrak',data.documents.length,'Fiziksel ve dijital')}${kpi('Teslim bekleyen',data.documents.filter(x=>x.status==='Teslim onayı bekliyor').length,'Alıcı onayı gerekli','','urgent')}${kpi('Geciken',data.documents.filter(x=>x.status==='Gecikmiş').length,'Teslim süresi aşıldı','','critical')}${kpi('Zimmetli',data.documents.filter(x=>x.status==='Zimmetli').length,'Personel üzerinde')}</div><div class="toolbar"><input class="input search" placeholder="Evrak no, kişi veya konu ara…" value="${esc(filter)}" oninput="filter=this.value;render()"></div>${card('Evrak zinciri',documentTable(list))}`}
function documentTable(a){return `<div class="table-wrap"><table><thead><tr><th>EVRAK</th><th>KONU</th><th>VEREN</th><th>ALAN</th><th>ŞU ANDA KİMDE</th><th>SON TARİH</th><th>DURUM</th><th></th></tr></thead><tbody>${rows(a,x=>`<tr><td>${x.type}<small>${x.no}</small></td><td>${x.subject}</td><td>${x.from}</td><td>${x.to}</td><td><b>${x.holder}</b></td><td>${fmt(x.due)}</td><td>${badge(x.status)}</td><td><button class="link" onclick="openDetail('document',${x.id})">Hareketler ›</button></td></tr>`,8)}</tbody></table></div>`}

function accounts(){const list=data.accounts.filter(x=>(role!=='procurement'||x.type==='Tedarikçi')&&(!filter||JSON.stringify(x).toLocaleLowerCase('tr').includes(filter.toLocaleLowerCase('tr'))));const overdue=data.accounts.filter(x=>x.days>0).reduce((s,x)=>s+x.due,0);return head('Cari & Vade Takibi','Müşteri ve tedarikçi carilerinin açık bakiyelerini, vadelerini ve takip görüşmelerini yönetin.')+`<div class="kpis">${kpi('Toplam açık bakiye',money(data.accounts.reduce((s,x)=>s+Math.abs(x.balance),0)),'Müşteri + tedarikçi')}${kpi('Vadesi geçen',money(overdue),'Gecikmiş açık tutar','','critical')}${kpi('Bugün vadeli',data.accounts.filter(x=>x.days===0).length,'Gün içinde takip','','urgent')}${kpi('7 gün içinde',4,'Yaklaşan vade')}</div><div class="toolbar"><input class="input search" placeholder="Cari adı, kodu veya sorumlu ara…" value="${esc(filter)}" oninput="filter=this.value;render()"></div>${card('Cari listesi',accountTable(list))}`}
function accountTable(a){return `<div class="table-wrap"><table><thead><tr><th>CARİ</th><th>TÜR</th><th>SORUMLU</th><th>BAKİYE</th><th>VADESİ GEÇEN</th><th>VADE</th><th>DURUM</th><th></th></tr></thead><tbody>${rows(a,x=>`<tr><td><b>${x.name}</b><small>${x.code}</small></td><td>${x.type}</td><td>${x.owner}</td><td>${money(x.balance)}</td><td class="${x.due?'amount-diff':''}">${money(x.due)}</td><td>${fmt(x.dueDate)}${x.days>0?`<small>${x.days} gün gecikti</small>`:''}</td><td>${badge(x.status)}</td><td><button class="link" onclick="openDetail('account',${x.id})">Cari kartı ›</button></td></tr>`,8)}</tbody></table></div>`}

function bank(){const list=data.bank.filter(x=>!filter||JSON.stringify(x).toLocaleLowerCase('tr').includes(filter.toLocaleLowerCase('tr')));return head('Banka Hareketleri','Havale ve EFT kayıtlarını cari ve açık faturalarla güven oranına göre eşleştirin.',`<button class="btn" onclick="notify('Banka hareketleri demo olarak yenilendi.')">Hareketleri yenile</button>`)+`<div class="kpis">${kpi('Bugün hareket',data.bank.length,'2 banka hesabı')}${kpi('Otomatik eşleşen',data.bank.filter(x=>x.status==='Otomatik eşleşti').length,'%98 güven')}${kpi('Onay bekleyen',data.bank.filter(x=>x.status==='Onay bekliyor').length,'Finans kararı gerekli','','urgent')}${kpi('Cari bulunamayan',data.bank.filter(x=>x.status==='Cari bulunamadı').length,'Manuel eşleştirme','','critical')}</div><div class="toolbar"><input class="input search" placeholder="Gönderen, açıklama veya cari ara…" value="${esc(filter)}" oninput="filter=this.value;render()"></div>${card('Banka eşleştirme kuyruğu',bankTable(list))}`}
function bankTable(a){return `<div class="table-wrap"><table><thead><tr><th>TARİH / BANKA</th><th>GÖNDEREN</th><th>AÇIKLAMA</th><th>TUTAR</th><th>ÖNERİLEN CARİ / FATURA</th><th>GÜVEN</th><th>DURUM</th><th></th></tr></thead><tbody>${rows(a,x=>`<tr><td>${fmt(x.date)}<small>${x.bank}</small></td><td>${x.sender}<small>${x.iban}</small></td><td>${x.description}</td><td><b>${money(x.amount)}</b></td><td>${x.match||'—'}<small>${x.invoice||'Açık fatura seçilmedi'}</small></td><td>%${x.confidence}</td><td>${badge(x.status)}</td><td>${x.status==='Otomatik eşleşti'?'<span class="muted">Tamamlandı</span>':`<button class="link" onclick="openDetail('bank',${x.id})">Eşleştir ›</button>`}</td></tr>`,8)}</tbody></table></div>`}

function offers(){return head('Teklif Yönetimi','Teklifleri hazırlayın, WhatsApp veya bağlantı ile paylaşın ve müşteri etkileşimini takip edin.',`<button class="btn primary" onclick="openForm('offer')">+ Yeni teklif</button>`)+`<div class="kpis">${kpi('Açık teklif','3','Toplam '+money(2792000))}${kpi('Görüntülenen','1','3 müşteri görüntülemesi')}${kpi('Revizyon','1','Müşteri geri bildirimi','','urgent')}${kpi('Kabul edilen','1',money(1925000))}</div><div class="kanban">${['Taslak','Gönderildi','Görüntülendi','Revizyon istendi','Kabul edildi','Süresi geçti'].map(s=>`<section class="lane"><h3>${s}<span>${data.offers.filter(x=>x.status===s).length}</span></h3>${data.offers.filter(x=>x.status===s).map(x=>`<div class="ticket"><b>${x.no}</b><strong>${x.customer}</strong><small>${x.title}</small><p>${money(x.amount)}</p><button class="link" onclick="openDetail('offer',${x.id})">Teklifi aç ›</button></div>`).join('')||'<small class="muted">Kayıt yok</small>'}</section>`).join('')}</div>`}

function catalog(){return head('Katalog, Video & QR','Ürün ve hizmet içeriklerini tek merkezden web sitesine ve QR kataloglara yayınlayın.',`<button class="btn primary" onclick="openForm('catalog')">+ Katalog kaydı</button>`)+`<div class="kpis">${kpi('Katalog kaydı',data.catalog.length,'Hizmet ve menüler')}${kpi('Web sitesinde',data.catalog.filter(x=>x.site).length,'Aktif yayın')}${kpi('Tanıtım videosu',data.catalog.filter(x=>x.media.includes('1 video')).length,'Video eklenmiş')}${kpi('İçerik eksik',data.catalog.filter(x=>!x.site).length,'Yayın öncesi tamamlanmalı','','urgent')}</div><div class="region-grid">${data.catalog.map(x=>`<article class="region"><div class="between"><span class="badge purple">${x.category}</span>${badge(x.status)}</div><h3>${x.name}</h3><p class="muted">${x.media}</p><div class="notice"><b>QR</b> · ${x.qr}</div><div class="between"><label class="checkbox"><input type="checkbox" ${x.site?'checked':''} onchange="toggleCatalog(${x.id},this.checked)"> Web sitesinde göster</label><button class="link" onclick="notify('QR bağlantısı panoya kopyalandı (demo).')">QR aç</button></div></article>`).join('')}</div>`}

function webai(){return head('Web Sitesi & AI Denetimi','SEO, rakip analizi, haftalık içerikler ve yemek listesi yayınını onaylı bir akışta yönetin.',`<button class="btn" onclick="notify('Yeni site taraması başlatıldı (demo).')">Siteyi şimdi tara</button>`)+`<div class="kpis">${kpi('Site sağlık puanı','82 / 100','Geçen haftaya göre +6')}${kpi('Açık SEO görevi','2','1 yüksek öncelik','','urgent')}${kpi('Haftalık içerik','2 / 2','Planlanan taslak hazır')}${kpi('Menü yayın onayı','1','28 Eylül–2 Ekim','','urgent')}</div><div class="grid"><div class="stack">${card('AI denetim görevleri',`<div class="table-wrap"><table><thead><tr><th>TÜR</th><th>GÖREV</th><th>ETKİ</th><th>DURUM</th><th></th></tr></thead><tbody>${rows(data.ai,x=>`<tr><td>${x.type}</td><td><b>${x.title}</b><small>${x.detail}</small></td><td>${x.impact}</td><td>${badge(x.status)}</td><td>${/onay/i.test(x.status)?`<button class="link" onclick="approveAI(${x.id})">Onayla ve yayınla</button>`:'<button class="link" onclick="notify(\'Görev sorumluya atandı.\')">Görev oluştur</button>'}</td></tr>`,5)}</tbody></table></div>`)}</div><div class="stack">${card('Rakip ve referans görünümü',`<div class="cardbody"><div class="statline"><span>Yerinde üretim içerik derinliği</span><b>6 / 10</b></div><div class="statline"><span>Mobil hız</span><b>78 / 100</b></div><div class="statline"><span>Referans çeşitliliği</span><b>4 sektör</b></div><div class="statline"><span>Yerel SEO görünürlüğü</span><b>%64</b></div><p class="muted">Karşılaştırma temsili rakip ölçümleriyle hazırlanmıştır.</p></div>`)}${card('Yayın güvenliği',`<div class="cardbody"><div class="notice">Yapay zekâ öneri ve taslak üretir. Web sitesi, katalog ve yemek listesi değişiklikleri yetkili onayı olmadan yayınlanmaz.</div></div>`)}</div></div>`}

function closeModal(){$('#modal').innerHTML='';document.body.style.overflow=''}
function modal(title,body,footer=''){document.body.style.overflow='hidden';$('#modal').innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><section class="modal-card" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="btn small" onclick="closeModal()">✕</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`}
function openForm(type){const forms={material:[role==='driver'?'Teslimat kaydet':'Yeni malzeme hareketi',`<div class="form-grid"><div class="field"><label>Hareket türü</label><select id="fType" class="input"><option>Giriş</option><option>Çıkış</option><option>Transfer</option></select></div><div class="field"><label>Bölge</label><select id="fRegion" class="input">${REGIONS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Malzeme</label><input id="fItem" class="input" value="Kuru fasulye"></div><div class="field"><label>Cari / tedarikçi</label><input id="fVendor" class="input" value="İstanbul Gıda"></div><div class="field"><label>Miktar</label><input id="fQty" type="number" class="input" value="50"></div><div class="field"><label>Birim</label><select id="fUnit" class="input"><option>kg</option><option>adet</option><option>koli</option><option>litre</option></select></div><div class="field full"><label>İrsaliye / evrak no</label><input id="fDoc" class="input" value="IRS-DEMO-01"></div></div>`],expense:['Yeni harcama',`<div class="form-grid"><div class="field"><label>Bölge</label><select id="fRegion" class="input">${REGIONS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Harcama türü</label><select id="fCategory" class="input"><option>Akaryakıt</option><option>Otopark</option><option>Otoyol</option><option>Acil malzeme</option><option>Bakım / Onarım</option></select></div><div class="field"><label>Cari</label><input id="fVendor" class="input" value="Kaya Petrol"></div><div class="field"><label>Tutar</label><input id="fAmount" type="number" class="input" value="100"></div><div class="field"><label>Ödeme yöntemi</label><select id="fPay" class="input"><option>Şirket kartı</option><option>Nakit</option><option>Havale</option></select></div><div class="field"><label>Belge</label><input id="fDoc" class="input" value="Fis_demo.jpg"></div><div class="field full"><label>Açıklama</label><textarea id="fNote" class="input">Demo harcama kaydı</textarea></div></div>`],purchase:['Yeni satın alma',`<div class="form-grid"><div class="field"><label>Bölge</label><select id="fRegion" class="input">${REGIONS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Tedarikçi</label><input id="fVendor" class="input" value="İstanbul Gıda"></div><div class="field"><label>Ürün</label><input id="fItem" class="input" value="Kuru fasulye"></div><div class="field"><label>Miktar</label><input id="fQty" type="number" class="input" value="100"></div><div class="field full"><label>Beklenen toplam</label><input id="fAmount" type="number" class="input" value="12500"></div></div>`],document:['Yeni evrak kaydı',`<div class="form-grid"><div class="field"><label>Evrak türü</label><select id="fType" class="input"><option>İrsaliye</option><option>Fatura</option><option>Sözleşme</option><option>Araç Evrakı</option></select></div><div class="field"><label>Evrak no</label><input id="fDoc" class="input" value="EVR-DEMO-01"></div><div class="field"><label>Veren</label><input id="fFrom" class="input" value="Murat Çelik"></div><div class="field"><label>Alan</label><input id="fTo" class="input" value="Havva Demir"></div><div class="field full"><label>Konu</label><input id="fNote" class="input" value="Demo teslim evrakı"></div></div>`],offer:['Yeni teklif',`<div class="form-grid"><div class="field"><label>Müşteri</label><input id="fCustomer" class="input" value="Yeni Müşteri A.Ş."></div><div class="field"><label>Hizmet</label><input id="fTitle" class="input" value="Yerinde üretim · 300 kişi"></div><div class="field"><label>Teklif tutarı</label><input id="fAmount" type="number" class="input" value="850000"></div><div class="field"><label>Geçerlilik</label><input id="fValid" type="date" class="input" value="2026-10-15"></div></div>`],catalog:['Yeni katalog kaydı',`<div class="form-grid"><div class="field"><label>Başlık</label><input id="fTitle" class="input" value="Özel Gün Menüsü"></div><div class="field"><label>Kategori</label><select id="fCategory" class="input"><option>Menü</option><option>Hizmet</option></select></div><div class="field full"><label>Açıklama</label><textarea id="fNote" class="input">Kurumsal organizasyonlara özel seçkiler.</textarea></div></div>`],delivery:['Teslimat kaydet',`<div class="notice">ATR Sakarya’dan alınan 48 koli Ayçiçek yağı · Hedef: Haseki ATR</div><div class="form-grid" style="margin-top:16px"><div class="field"><label>Teslim edilen miktar</label><input id="fQty" type="number" class="input" value="48"></div><div class="field"><label>Teslim alan</label><input id="fTo" class="input" value="Emre Aydın"></div></div>`]};const [title,body]=forms[type];modal(title,body,`<button class="btn" onclick="closeModal()">Vazgeç</button><button class="btn primary" onclick="submitForm('${type}')">Kaydet ve merkeze bildir</button>`)}
function val(id){return document.getElementById(id)?.value||''}
function submitForm(type){if(type==='material'||type==='delivery'){data.materials.unshift({id:Date.now(),date:'2026-09-27',region:val('fRegion')||'Haseki ATR',type:type==='delivery'?'Transfer':'Giriş',item:val('fItem')||'Ayçiçek yağı',qty:Number(val('fQty'))||48,unit:val('fUnit')||'koli',supplier:val('fVendor')||'Merkez Depo',person:ROLES[role].person,document:val('fDoc')||'TRF-221',status:'Kontrol bekliyor',issue:''})}else if(type==='expense'){data.expenses.unshift({id:Date.now(),date:'2026-09-27',person:ROLES[role].person,role:ROLES[role].label,region:val('fRegion'),category:val('fCategory'),vendor:val('fVendor'),declared:Number(val('fAmount')),invoice:null,payment:val('fPay'),doc:val('fDoc'),status:'Fatura bekliyor',note:val('fNote')})}else if(type==='purchase'){data.purchases.unshift({id:Date.now(),no:'SA-2026-DEMO',date:'2026-09-27',region:val('fRegion'),supplier:val('fVendor'),item:val('fItem'),qty:Number(val('fQty')),received:null,expected:Number(val('fAmount')),invoice:0,invoiceNo:'—',status:'Fatura bekliyor'})}else if(type==='document'){data.documents.unshift({id:Date.now(),type:val('fType'),no:val('fDoc'),subject:val('fNote'),from:val('fFrom'),to:val('fTo'),holder:val('fFrom'),due:'2026-09-30',status:'Teslim onayı bekliyor',history:['27.09 · '+val('fFrom')+' tarafından '+val('fTo')+' kişisine gönderildi']})}else if(type==='offer'){data.offers.unshift({id:Date.now(),no:'TKL-2026-DEMO',customer:val('fCustomer'),title:val('fTitle'),amount:Number(val('fAmount')),valid:val('fValid'),owner:ROLES[role].person,status:'Taslak',channel:'—',views:0})}else if(type==='catalog'){data.catalog.unshift({id:Date.now(),name:val('fTitle'),category:val('fCategory'),media:'Medya bekliyor',qr:'CM-DEMO-'+(data.catalog.length+1),site:false,status:'Hazırlanıyor'})}save();closeModal();render();notify('Kayıt oluşturuldu ve ilgili merkeze bildirildi.')}

function openDetail(type,id){const x=data[type==='purchase'?'purchases':type==='material'?'materials':type==='document'?'documents':type==='account'?'accounts':type==='bank'?'bank':'offers'].find(y=>y.id===id);if(type==='material')modal('Malzeme hareketi',`<div class="form-grid"><div class="field"><label>Hareket</label><b>${x.type}</b></div><div class="field"><label>Bölge</label><b>${x.region}</b></div><div class="field"><label>Malzeme</label><b>${x.item}</b></div><div class="field"><label>Miktar</label><b>${x.qty} ${x.unit}</b></div><div class="field"><label>Tedarikçi</label><b>${x.supplier}</b></div><div class="field"><label>İrsaliye</label><b>${x.document}</b></div></div>${x.issue?`<div class="notice danger" style="margin-top:18px">${x.issue}</div>`:''}`,x.status!=='Onaylandı'?`<button class="btn primary" onclick="complete('materials',${id},'Onaylandı')">Hareketi onayla</button>`:'');
 else if(type==='purchase')modal('Fatura kontrolü · '+x.invoiceNo,`<div class="notice ${x.status==='Tam eşleşti'?'':'danger'}">${x.status==='Tam eşleşti'?'Şube kontrolü tamamlandı; kayıt aylık maliyete alındı.':'Alarm: '+x.status}</div>${x.region==='Belirsiz'?`<div class="field" style="margin-top:18px"><label>Manuel şube / proje yönlendirmesi</label><select id="routeRegion" class="input">${REGIONS.map(r=>`<option>${r}</option>`).join('')}</select></div>`:''}<div class="form-grid" style="margin-top:18px"><div class="field"><label>Satın alma miktarı</label><b>${x.qty??'—'}</b></div><div class="field"><label>Mal kabul miktarı</label><b>${x.received??'—'}</b></div><div class="field"><label>Beklenen tutar</label><b>${x.expected==null?'—':money(x.expected)}</b></div><div class="field"><label>Gelen fatura</label><b>${money(x.invoice)}</b></div><div class="field full"><label>Tedarikçi / Fatura</label><b>${x.supplier} · ${x.invoiceNo}</b></div></div>`,purchaseFooter(x,id));
 else if(type==='document')modal('Evrak hareket geçmişi',`<div class="notice"><b>${x.type} · ${x.no}</b><br>${x.subject}<br>Şu anda: ${x.holder}</div><div class="timeline" style="margin-top:20px">${x.history.map(h=>`<div class="timeline-item"><strong>${h}</strong></div>`).join('')}</div>`,x.status==='Teslim onayı bekliyor'?`<button class="btn primary" onclick="acceptDocument(${id})">Teslim aldım</button>`:`<button class="btn primary" onclick="transferDocument(${id})">Başka kişiye ver</button>`);
 else if(type==='account')modal('Cari kartı · '+x.name,`<div class="kpis" style="grid-template-columns:repeat(2,1fr)">${kpi('Bakiye',money(x.balance),'Cari toplamı')}${kpi('Vadesi geçen',money(x.due),x.days>0?x.days+' gün gecikti':'Gecikme yok')}</div><div class="notice"><b>Sorumlu:</b> ${x.owner}<br><b>Son bildirim:</b> ${x.days>0?'26.09.2026 · Ödeme hatırlatması yapıldı':'Bildirim bulunmuyor'}</div><label class="field" style="margin-top:16px"><label>Görüşme sonucu</label><textarea id="followNote" class="input" placeholder="Ödeme sözü, görüşme notu…"></textarea></label>`,`<button class="btn primary" onclick="saveFollow(${id})">Takip notunu kaydet</button>`);
 else if(type==='bank')modal('Banka hareketini eşleştir',`<div class="notice"><b>${x.sender}</b><br>${x.description} · ${money(x.amount)}</div><div class="form-grid" style="margin-top:18px"><div class="field full"><label>Cari</label><select id="bankAccount" class="input">${data.accounts.map(a=>`<option ${x.match===a.name?'selected':''}>${a.name}</option>`).join('')}</select></div><div class="field full"><label>Açık fatura</label><select id="bankInvoice" class="input"><option>KBR-2026-0912 · ${money(x.amount)}</option><option>KBR-2026-0881 · ${money(74100)}</option><option>Avans / faturaya bağlama</option></select></div></div>`,`<button class="btn primary" onclick="matchBank(${id})">Eşleşmeyi onayla</button>`);
 else modal('Teklif · '+x.no,`<div class="form-grid"><div class="field"><label>Müşteri</label><b>${x.customer}</b></div><div class="field"><label>Geçerlilik</label><b>${fmt(x.valid)}</b></div><div class="field full"><label>Hizmet</label><b>${x.title}</b></div><div class="field"><label>Tutar</label><b>${money(x.amount)}</b></div><div class="field"><label>Görüntülenme</label><b>${x.views}</b></div></div><div class="pill-row" style="margin-top:20px"><button class="btn" onclick="shareOffer(${id},'WhatsApp')">WhatsApp’tan paylaş</button><button class="btn" onclick="shareOffer(${id},'E-posta')">E-posta</button><button class="btn" onclick="shareOffer(${id},'Bağlantı')">Bağlantı kopyala</button><button class="btn">PDF indir</button></div>`)}
function complete(collection,id,status){const x=data[collection].find(x=>x.id===id);x.status=status;save();closeModal();render();notify('Kontrol tamamlandı ve kayıt güncellendi.')}
function acceptDocument(id){const x=data.documents.find(x=>x.id===id);x.holder=x.to;x.status='Teslim alındı';x.history.push('27.09 · '+x.to+' teslim aldı');save();closeModal();render();notify('Evrak teslim alındı.')}
function transferDocument(id){const x=data.documents.find(x=>x.id===id);x.from=x.holder;x.to='Havva Demir';x.status='Teslim onayı bekliyor';x.history.push('27.09 · '+x.from+' tarafından Havva Demir’e gönderildi');save();closeModal();render();notify('Yeni evrak transferi oluşturuldu.')}
function purchaseFooter(x,id){if(x.status==='Tam eşleşti')return '';if(x.region==='Belirsiz'&&role==='manager')return `<button class="btn primary" onclick="routeInvoice(${id})">Şubeye yönlendir</button>`;if(role==='branch')return `<button class="btn" onclick="notify('Düzeltme talebi satın almaya iletildi.')">Düzeltme iste</button><button class="btn primary" onclick="complete('purchases',${id},'Tam eşleşti')">Şube kontrolünü onayla</button>`;return `<button class="btn" onclick="notify('Kayıt ilgili sorumluya atandı.')">Düzeltme iste</button><button class="btn primary" onclick="complete('purchases',${id},'Tam eşleşti')">Kontrol edildi</button>`}
function routeInvoice(id){const x=data.purchases.find(x=>x.id===id);x.region=val('routeRegion');x.status='Mal kabul bekliyor';save();closeModal();render();notify('Fatura seçilen şubeye yönlendirildi. Yönetici için ikinci onay oluşmadı.')}
function saveFollow(id){const note=val('followNote').trim();if(!note)return notify('Takip notu girin.');const x=data.accounts.find(x=>x.id===id);x.lastNote=note;x.lastFollow='27.09.2026';save();closeModal();render();notify('Cari takip notu kaydedildi ve sorumluya bildirildi.')}
function matchBank(id){const x=data.bank.find(x=>x.id===id);x.match=val('bankAccount');x.invoice=val('bankInvoice').split(' · ')[0];x.status='Manuel eşleşti';x.confidence=100;save();closeModal();render();notify('Banka hareketi cariye ve faturaya eşleştirildi.')}
function shareOffer(id,channel){const x=data.offers.find(x=>x.id===id);x.channel=channel;if(x.status==='Taslak')x.status='Gönderildi';save();closeModal();render();notify('Teklif '+channel+' için paylaşılabilir bağlantıyla hazırlandı (demo).')}
function toggleCatalog(id,on){const x=data.catalog.find(x=>x.id===id);x.site=on;x.status=on?'Yayında':'Hazırlanıyor';save();render();notify(on?'Katalog web sitesinde yayınlandı.':'Katalog web sitesinden kaldırıldı.')}
function approveAI(id){const x=data.ai.find(x=>x.id===id);x.status='Yayınlandı';save();render();notify(x.type==='Yemek Listesi'?'Yemek listesi web sitesi ve QR menüde yayınlandı.':'İçerik web sitesinde yayınlandı.')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
